css:
.fx-bks{width:min(520px,100%);border:1px solid var(--border);border-radius:var(--radius);padding:1.3em;background:var(--surface)}
.fx-bks .days{display:flex;gap:.5em;overflow-x:auto;padding-bottom:.6em;margin-bottom:1em}
.fx-bks .days button{flex:0 0 auto;min-width:4.4em;padding:.6em .5em;border-radius:calc(var(--radius)*.7);border:1px solid var(--border);background:none;color:var(--text);text-align:center;font:600 .85em var(--font-body);cursor:pointer;line-height:1.3}
.fx-bks .days button b{display:block;font-size:1.4em;font-family:var(--font-heading)}
.fx-bks .days button[aria-selected=true]{background:var(--primary);color:var(--on-primary);border-color:var(--primary)}
.fx-bks .slots{display:grid;grid-template-columns:repeat(4,1fr);gap:.5em;min-height:7.6em}
.fx-bks .slots button{padding:.7em 0;border:1px solid var(--border);border-radius:calc(var(--radius)*.6);background:none;color:var(--text);font:600 .9em var(--font-body);cursor:pointer;transition:all calc(.15s/var(--speed))}
.fx-bks .slots button:hover:not(:disabled){border-color:var(--primary)}
.fx-bks .slots button:disabled{opacity:.35;text-decoration:line-through;cursor:not-allowed}
.fx-bks .slots button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-bks .sum{display:flex;justify-content:space-between;align-items:center;gap:1em;margin-top:1.2em;padding-top:1em;border-top:1px dashed var(--border);font-size:.92em}
.fx-bks .sum button{background:var(--primary);color:var(--on-primary);border:0;border-radius:99px;padding:.7em 1.3em;font:700 .92em var(--font-body);cursor:pointer}
.fx-bks .sum button:disabled{opacity:.4;cursor:not-allowed}
@media(prefers-reduced-motion:reduce){.fx-bks .slots button{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-bks .slots button.is-tap:not(:disabled){border-color:var(--primary)}

js:
(function(){var r=document.querySelector('.fx-bks'),dv=r.querySelector('.days'),sv=r.querySelector('.slots'),s=r.querySelector('#fx-bks-s'),cb=r.querySelector('.sum button');
var D=['Mon','Tue','Wed','Thu','Fri','Sat'],T=['10:00','11:00','12:00','13:00','14:30','15:30','16:30','18:00'],day=0,sel=null,now=new Date();
function taken(d,t){return (d*7+t*3)%5===0}
function days(){D.forEach(function(n,i){var b=document.createElement('button');b.type='button';b.setAttribute('role','tab');b.innerHTML=n+'<b>'+(10+i)+'</b>';b.onclick=function(){day=i;sel=null;draw()};dv.appendChild(b)})}
function draw(){[].forEach.call(dv.children,function(b,i){b.setAttribute('aria-selected',i===day)});sv.innerHTML='';
T.forEach(function(t,i){var b=document.createElement('button');b.type='button';b.textContent=t;b.disabled=taken(day,i);b.setAttribute('aria-pressed',sel===i);b.onclick=function(){sel=i;draw()};sv.appendChild(b)});
s.textContent=sel===null?'Choose a time':D[day]+' '+(10+day)+' · '+T[sel];cb.disabled=sel===null}
days();draw()})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
